WITH ValidTransactions AS (SELECT *, CONCAT_WS('/', merchant, txn_type) AS merchant_txn_type_key FROM transactions WHERE account_id = 4 AND (account_id = 30 OR is_flagged = TRUE)), agg AS (SELECT CASE WHEN amount >= 4000 THEN 'high' WHEN amount >= 1700 THEN 'mid' ELSE 'low' END AS amount_bucket, MAX(txn_time) AS latest_txn_time, SORT_ARRAY(COLLECT_SET(merchant)) AS merchant_list FROM ValidTransactions GROUP BY CASE WHEN amount >= 4000 THEN 'high' WHEN amount >= 1700 THEN 'mid' ELSE 'low' END) SELECT * FROM agg ORDER BY amount_bucket LIMIT 50;
